// Define target agricultural fields with agronomic thresholds
const fields = [
  { id: 'cmvpap35100019ep849ii6yh8', name: 'Field A (Sector 1)', crop: 'Boro Rice (BRRI dhan28)', threshold: 35 },
  { id: 'cmvpap35100029ep8d89s89sd', name: 'Field B (Sector 2)', crop: 'Wheat (BARI Gom-33)', threshold: 30 },
  { id: 'cmvpap35100039ep8k1928374', name: 'Field C (Sector 3)', crop: 'Mustard (BARI Sarisha-14)', threshold: 28 },
  { id: 'cmvpap4sa00049ep8h1tm3ow6', name: 'Field D (Sector 4)', crop: 'Potato (Diamant)', threshold: 40 }
];

const now = new Date();
const currentHour = now.getHours() + now.getMinutes() / 60;

// Diurnal Solar Cycle (24h sinusoid: peak warmth at 14:00, coolest at 05:00)
const solarCycle = Math.sin(((currentHour - 8) * Math.PI) / 12);

// Base diurnal temperature (coolest 22°C at dawn, warmest 33°C in early afternoon)
const baseTemp = 27.5 + 5.5 * solarCycle;
// Inverse diurnal relative humidity (drier 48% at afternoon peak, humid 88% at dawn)
const baseHumidity = 68 - 18 * solarCycle;

const items = [];

for (const field of fields) {
  const tempJitter = (Math.random() - 0.5) * 1.5;
  const humJitter = (Math.random() - 0.5) * 4.0;

  const temperature = Math.round((baseTemp + tempJitter) * 10) / 10;
  const humidity = Math.min(100, Math.max(20, Math.round((baseHumidity + humJitter) * 10) / 10));

  // Soil moisture random-walk in range 20% - 60%
  // Daytime evaporation decreases moisture slightly
  const evapFactor = solarCycle > 0 ? solarCycle * 2.5 : 0;
  const baseMoisture = field.threshold + (Math.random() * 14 - 5) - evapFactor;
  const soilMoisture = Math.min(60, Math.max(20, Math.round(baseMoisture * 10) / 10));

  // Soil pH: slightly acidic to neutral alluvial soil (6.10 - 6.90)
  const ph = Math.round((6.5 + (Math.random() - 0.5) * 0.4) * 100) / 100;

  items.push({
    json: {
      fieldId: field.id,
      fieldName: field.name,
      crop: field.crop,
      threshold: field.threshold,
      soilMoisture,
      temperature,
      humidity,
      ph,
      isBelowThreshold: soilMoisture < field.threshold,
      recordedAt: now.toISOString()
    }
  });
}

return items;

